    private _rightMargin;
    private _topMargin;
    private _bottomMargin;
    private _extension;
    private _roundMargins;
    private readonly _fillProperty;
    private readonly _borderOverrideProperty;
    private readonly _borderProperty;
    private readonly roundedShape;
    private readonly rectangularShape;
    private readonly leftSide;
    private readonly rightSide;
    private readonly topSide;
    private readonly bottomSide;
    private readonly topLeftCorner;
    private readonly topRightCorner;
    private readonly bottomLeftCorner;
    private readonly bottomRightCorner;
    constructor(providedOptions?: GradientRectangleOptions);
    /**
     * Updates the rounded-ness of the margins.
     */
    private invalidateRoundMargins;
    /**
     * Updates the rounded-ness of the margins.
     */
